import{z as n,x as s,o as B,c as d,q as e,j as o,D as a,d as A,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"利率走廊的理论","description":"","frontmatter":{"title":"利率走廊的理论","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-corridor-theory.md","filePath":"econ/mt-corridor-theory.md","lastUpdated":1791413859000}'),l={name:"econ/mt-corridor-theory.md"};function _(p,E,c,h,C,m){const r=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=e('<h1 id="利率走廊的理论" tabindex="-1">利率走廊的理论 <a class="header-anchor" href="#利率走廊的理论" aria-label="Permalink to &quot;利率走廊的理论&quot;">​</a></h1><div class="epigraph"><p>价格由承诺决定，数量由支付决定；把二者混为一谈，就会把准备金的洪水误读成政策的洪水。</p><footer>—— 据 Bindseil 对货币政策实施的整理；Woodford, Interest and Prices, 2003</footer></div><p><a href="/econ/mt-digital-currency-theory">上一课</a>讨论央行负债发给谁之后，回到最古典的环节：无论目标定在哪、规则写成什么样，央行最终都要把市场利率钉在宣布的位置 \\(i^{*}\\) 上。基线课的<a href="/econ/ior-corridor-floor">准备金利息与走廊</a>已给出走廊与地板的操作框架，并留下「资产负债表规模不是松紧的充分统计」这条经验；本课深化它的理论：套利论证为什么夹得住利率、走廊宽度的取舍、以及量价分离的模型位置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>央行对市场交易没有强制力，凭什么市场利率听它的？答案是一个两边的套利论证。准备金利息 \\(i_{d}\\) 给持有准备金设定无风险底价：没有银行愿意以低于 \\(i_{d}\\) 的利率把资金借给市场，因为存回央行无风险且更优。借贷便利 \\(i_{l}\\) 给流动性设定顶价：没有银行为头寸支付高于 \\(i_{l}\\) 的利率。于是市场利率被夹在 \\([i_{d},\\, i_{l}]\\) 内，走廊宽度</p> \\[s = i_{l} - i_{d} \\]<p>就是这套机制的公差。只要支付摩擦与准备金分布的离散度小于 \\(s\\)，不需要任何一笔强制交易，市场利率就被套利钉住。</p><p><span class="marginnote">直觉类比：走廊像给市场利率装的一副「护栏」——利率想往下掉，银行宁愿把钱存回央行稳拿 \\(i_{d}\\)；想往上冲，银行宁可找央行借 \\(i_{l}\\)。央行无需强买强卖，套利自己把价格夹进护栏。</span></p><p><span class="marginnote">数字实例：若 \\(i_{d}=1.90\\%\\)、\\(i_{l}=2.10\\%\\)，走廊宽度 \\(s\\) 就是 20 个基点。只要日间支付摩擦造成的拆借利率摆动不超过这 20 个基点，市场利率就出不了区间；地板系统更进一步——直接把目标利率设在底价 \\(i_{d}\\) 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走廊宽度把体系分成两种运行状态。<strong>稀缺准备金</strong>（走廊系统）：央行把供给放在需求曲线的陡峭段，量的边际误差直接变成价的误差——数量是工具，央行必须每天精确预测支付摩擦引起的准备金需求。<strong>充足准备金</strong>（地板系统）：供给远超需求，需求曲线在平坦段，市场利率贴着 \\(i_{d}\\)；数量失去边际含义，价格即政策，央行从「算准量」的工程师变成「宣布价」的机构。地板的代价是常备的超额准备金存量，收益是把准备金预测误差这个整类风险从政策里删除。</p><p>量价分离有更深的一层。Woodford 2003 的近现金极限论证：当央行负债充分计息、利率规则满足确定性条件时，价格水平由利率规则决定，与货币数量脱钩——这正是<a href="/econ/woodford-interest">Woodford 利息与价格</a>附录的骨架，也是<a href="/econ/quantity-theory">数量方程与货币中性</a>在操作层面的修正：\\(M\\) 内生于支付需求（<a href="/econ/reserve-endogenous-money">准备金、乘数与内生货币</a>），不再是政策立场的光学读数。</p>',12)),(B(),o(i,null,{default:a(()=>[t(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22IOR%20%E8%AE%BE%E5%BA%95%E4%BB%B7%20i_d%22%5D%20--%3E%20CLIP%5B%22%E5%B8%82%E5%9C%BA%E5%88%A9%E7%8E%87%E8%A2%AB%E5%A5%97%E5%88%A9%E5%A4%B9%E4%BD%8F%22%5D%0A%20%20B%5B%22%E5%80%9F%E8%B4%B7%E4%BE%BF%E5%88%A9%E8%AE%BE%E9%A1%B6%E4%BB%B7%20i_l%22%5D%20--%3E%20CLIP%0A%20%20CLIP%20--%3E%20W%7B%22%E8%B5%B0%E5%BB%8A%E5%AE%BD%E5%BA%A6%20s%20%E4%B8%8E%E5%87%86%E5%A4%87%E9%87%91%E4%BE%9B%E7%BB%99%22%7D%0A%20%20W%20--%3E%7C%22%E7%A8%80%E7%BC%BA%EF%BC%9A%E4%BE%9B%E7%BB%99%E5%9C%A8%E9%99%A1%E5%B3%AD%E6%AE%B5%22%7C%20COR%5B%22%E8%B5%B0%E5%BB%8A%E7%B3%BB%E7%BB%9F%EF%BC%9A%E6%95%B0%E9%87%8F%E6%98%AF%E5%B7%A5%E5%85%B7%22%5D%0A%20%20W%20--%3E%7C%22%E5%85%85%E8%B6%B3%EF%BC%9A%E4%BE%9B%E7%BB%99%E5%9C%A8%E5%B9%B3%E5%9D%A6%E6%AE%B5%22%7C%20FLR%5B%22%E5%9C%B0%E6%9D%BF%E7%B3%BB%E7%BB%9F%EF%BC%9AIOR%20%E5%8D%B3%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20FLR%20--%3E%20SEP%5B%22%E9%87%8F%E4%BB%B7%E5%88%86%E7%A6%BB%EF%BC%9A%E8%A1%A8%E8%A7%84%E6%A8%A1%E9%9D%9E%E6%9D%BE%E7%B4%A7%E8%AF%BB%E6%95%B0%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>走廊宽度的选择是一组权衡。宽走廊容忍日间支付摩擦（<a href="/econ/rtgs-payments">支付系统与 RTGS</a>）与准备金在银行间分布的异质性，但让利率的日间波动带着政策噪声；窄走廊逼近零宽时控制精度最高，却把所有摩擦推向借贷便利，最后贷款人从后备变成日常（<a href="/econ/lender-of-last-resort">最后贷款人</a>）。地板系统是窄走廊的极限稳定态：利率钉在 IOR，回购与货币基金市场的价格绕着它组织（<a href="/econ/repo-mmf">回购市场与货币市场基金</a>）。</p><p>「地板漏水」是这个理论的第一号边界：当准备金分布高度异质——部分机构（如政府支持企业）无权赚 IOR，银行可以借入低价资金再存回央行套利——有效利率会贴在 IOR 之下，地板不再水平。修复靠的是把付息面扩到对手方，或靠常备回购便利托底，这恰与<a href="/econ/cbdc">CBDC</a>把付息面扩到公众的「争夺走廊」逻辑同源：付息面扩到哪一层，价格钉在哪一层。</p>',3)),(B(),o(i,null,{default:a(()=>[t(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20HET%5B%22%E5%87%86%E5%A4%87%E9%87%91%E5%88%86%E5%B8%83%E9%AB%98%E5%BA%A6%E5%BC%82%E8%B4%A8%22%5D%20--%3E%20NOIOR%5B%22%E9%83%A8%E5%88%86%E6%9C%BA%E6%9E%84%E6%97%A0%E6%9D%83%E8%B5%9A%20IOR%22%5D%0A%20%20NOIOR%20--%3E%20LEND%5B%22%E5%AE%83%E4%BB%AC%E5%8F%AA%E8%83%BD%E4%BD%8E%E4%BB%B7%E5%87%BA%E5%80%9F%E8%B5%84%E9%87%91%22%5D%0A%20%20LEND%20--%3E%20ARB%5B%22%E9%93%B6%E8%A1%8C%E5%80%9F%E5%85%A5%E4%BD%8E%E4%BB%B7%E8%B5%84%E9%87%91%E5%86%8D%E5%AD%98%E5%9B%9E%E5%A4%AE%E8%A1%8C%E5%90%83%E6%81%AF%E5%B7%AE%22%5D%0A%20%20ARB%20--%3E%20SAG%5B%22%E6%9C%89%E6%95%88%E5%88%A9%E7%8E%87%E8%B7%8C%E7%A0%B4%20IOR%EF%BC%9A%E5%9C%B0%E6%9D%BF%E6%BC%8F%E6%B0%B4%22%5D%0A%20%20SAG%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%EF%BC%9A%E4%BB%98%E6%81%AF%E9%9D%A2%E6%89%A9%E5%A4%A7%20%2F%20%E5%B8%B8%E5%A4%87%E5%9B%9E%E8%B4%AD%E4%BE%BF%E5%88%A9%E6%89%98%E5%BA%95%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">判读一个体系走在廊还是在地板，看的不是准备金总量，而是「量的边际是否还有价格含义」。2008 年后美联储准备金扩张数倍而有效联邦基金利率钉在 IOR 附近，是量价分离最直接的自然实验。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的套利论证假定银行同质、支付摩擦外生；分布异质时地板会漏，如上所述。走廊理论也不涉及汇率干预与资本流动下的利率独立——那属于开放经济政策。要划清的另一条边界：地板系统下扩表不再是宽松信号，但缩表也不是对称的紧缩信号；<a href="/econ/central-bank-balance-sheet">央行资产负债表</a>的退出机制另有一套工程逻辑。至此目标、规则、预期、非常规工具、负债侧创新与实施机制全部就位，下一课收束整门课程。</p><p><span class="marginnote">常见误区：把「央行扩表」当成「放水降息」。地板系统下准备金再翻一倍，只要 IOR 不动，市场利率就不动——松紧读在价格上，不在资产负债表的规模上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>央行钉住利率靠双边套利：IOR 设底价，借贷便利设顶价，走廊宽度是公差。</li><li>稀缺系统里数量是工具，地板系统里 IOR 即价格、数量失去信号含义。</li><li>量价分离的模型位置是 Woodford 的近现金极限：利率规则决定价格，\\(M\\) 内生。</li><li>地板漏水与 CBDC 争夺走廊同源：付息面扩到哪层，价格钉在哪层。</li><li>出处：Bindseil 对货币政策实施的整理；Woodford, <em>Interest and Prices</em>, 2003；央行操作框架公开讨论。</li></ul>',6))])}const F=n(l,[["render",_]]);export{f as __pageData,F as default};
